console.log(`  python ms  -> base: ${base(new Date(fromPython)).toDateString()} | head: ${head(new Date(fromPython)).toDateString()}  (expected Fri Sep 20 2019)`)
console.log(`  toDateString -> base: ${base(new Date(fromSelect)).toDateString()} | head: ${head(new Date(fromSelect)).toDateString()}  (expected Mon Sep 16 2019)`)
EOF
